// Récupérer le sujet de l'email
const subject = $input.item.json.subject || '';

// Patterns possibles dans le sujet
const patternABC = /ABC-\d{4}-\d+-[A-Z0-9]{4}/i;                    // RFQ-2026-123-AB12

let abc_number = null;


const matchABC_Auto = subject.match(patternABC);
if (matchABC_Auto) {
  abc_number = matchABC_Auto[0].replace('#', '').toUpperCase().trim();
}



// Verifier si au moins un identifiant a ete trouve
if (!abc_number) {
  return {
    success: false,
    error: 'Aucun numéro ABC trouvé dans le sujet',
    subject_recu: subject,
    abc_number: null
  };
}


// Retourner les donnees
return {
  success: true,
  type_reference: 'ABC',
  abc_number: abc_number,
  subject_recu: subject,
  email_from: $input.item.json.from || '',
  email_body: $input.item.json.textPlain || '',
  date_reception: new Date().toISOString()
};

// ===== Données de l'email =====
const subject = $input.item.json.subject || '';
const fromRaw = $input.item.json.from || '';

// ===== Configuration =====
// Format : df-jjmmyyyy-4caractères  (ex: df-05112026-lkmo)
const patternDF = /\bdf-(0[1-9]|[12]\d|3[01])(0[1-9]|1[0-2])(\d{4})-([A-Z0-9]{4})\b/i;

const expediteursAutorises = [
  'Oumaima.Abouabdillah@cdm.ma',
  'Sanae.KandriIdrissi@cdm.ma',
  'Afaf.Abbadi@cdm.ma',
  'Ali.OUAZZANITOUHAMI@cdm.ma',
  'MohammedKabir.Naciri@cdm.ma'
].map(e => e.toLowerCase());

// ===== 1. Extraire l'adresse email de l'expéditeur =====
// "from" peut être : "Nom <mail@x.ma>", "mail@x.ma", ou un objet { text, value: [{address}] }
let fromText = '';
if (typeof fromRaw === 'string') {
  fromText = fromRaw;
} else if (fromRaw && fromRaw.value && fromRaw.value[0] && fromRaw.value[0].address) {
  fromText = fromRaw.value[0].address;
} else if (fromRaw && fromRaw.text) {
  fromText = fromRaw.text;
}

const emailMatch = fromText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const expediteurEmail = emailMatch ? emailMatch[0].toLowerCase() : null;

const expediteurValide = expediteurEmail !== null && expediteurailAutorise(expediteurEmail);

function expediteurailAutorise(email) {
  return expediteursAutorises.includes(email);
}

// ===== 2. Chercher l'identifiant DF dans le sujet =====
let df_number = null;
let df_date = null;
const matchDF = subject.match(patternDF);

if (matchDF) {
  const jour = parseInt(matchDF[1], 10);
  const mois = parseInt(matchDF[2], 10);
  const annee = parseInt(matchDF[3], 10);

  // Vérifier que la date existe vraiment (ex: 31/02 invalide)
  const d = new Date(annee, mois - 1, jour);
  const dateReelle = d.getFullYear() === annee && d.getMonth() === mois - 1 && d.getDate() === jour;

  if (dateReelle) {
    df_number = matchDF[0].toLowerCase();
    df_date = `${annee}-${String(mois).padStart(2, '0')}-${String(jour).padStart(2, '0')}`;
  }
}

// ===== 3. Résultat =====
const erreurs = [];
if (!df_number) erreurs.push('Aucun identifiant df-jjmmyyyy-xxxx valide dans le sujet');
if (!expediteurValide) erreurs.push('Expéditeur non autorisé');

if (erreurs.length > 0) {
  return {
    success: false,
    errors: erreurs,
    identifiant_trouve: !!df_number,
    expediteur_valide: expediteurValide,
    subject_recu: subject,
    email_from: expediteurEmail || fromText,
    df_number: df_number
  };
}

return {
  success: true,
  type_reference: 'DF',
  df_number: df_number,
  df_date: df_date,
  identifiant_trouve: true,
  expediteur_valide: true,
  subject_recu: subject,
  email_from: expediteurEmail,
  email_body: $input.item.json.textPlain || '',
  date_reception: new Date().toISOString()
};
